const pathToSettings = path.join(request.user.directories.root, SETTINGS_FILE);
if (Object.hasOwn(request.body, 'vc_changes')) {
    const vcCommit = globalThis[Symbol.for('virtual-companion.bridge')]?.commitDocument;
    if (!vcCommit) return response.status(503).json({ code: 'VC_DOCUMENT_UNAVAILABLE', message: 'Configuration unavailable' });
    return vcCommit(request, response, pathToSettings, { result: { result: 'ok' },
        write(next) { writeFileAtomicSync(pathToSettings, JSON.stringify(next, null, 4), 'utf8'); triggerAutoSave(request.user.profile.handle); } });
}
writeFileAtomicSync(pathToSettings, JSON.stringify(request.body, null, 4), 'utf8');
